router.post('/webhooks/paddle/subscription-cancelled', express.urlencoded({ extended: true }), async (req, res) => {
  const isVerified = paddleClient.verifyWebhook(req.body);
  if (!isVerified) return res.status(400).send('Invalid webhook signature');

  const { passthrough, subscription_id } = req.body;
  let metadata = {};
  try { metadata = JSON.parse(passthrough || '{}'); } catch(e) {}

  const companyId = metadata.companyId;
  if (companyId) {
    const company = await CompanyLicenses.findOne({
      where: { companyId, paddleSubscriptionId: subscription_id }
    });
    if (!company) {
      return res.status(403).send('Subscription ID does not match company license records');
    }

    await company.update({ activeSeats: 0, status: 'REVOKED' });
  }
  res.status(200).send('License cancellation processed');
});
